INSERT INTO `quest_request_items_locale` (`ID`,`Locale`,`CompletionText`,`VerifiedBuild`) VALUES
(14069,'frFR','Bon début, $gmonsieur:madame;, mais je vous suggère d''en faire un exemple avec quelques autres.',0),
(14070,'frFR','C''est tout ? Revérifions vite la liste, pour être sûrs.',0),
(14071,'frFR','La fête est presque prête. Comment s''est passé votre tour en ville ?',0),
(14075,'frFR','Je sais pas, patron. On me signale toujours des vers qui dévorent tout le kaja''mite dans les mines.$B$BVous devriez y retourner pour vous en occuper.',0),
(14093,'frFR','Les worgens ont-ils été neutralisés ?',0),
(14098,'frFR','Avez-vous réussi, $n ?',0),
(14113,'frFR','Comment se passe la fête ?$B$BVous êtes superbe ! Si $gélégant:élégante; et si $gbeau:belle;, $gmonsieur:madame; !',0),
(14115,'frFR','C''était tous ? Je suis sûr d''en avoir vu beaucoup débarquer !',0),
(14218,'frFR','Nous devons en abattre autant que possible, $n.',0),
(14222,'frFR','Nous pouvons y arriver, $n.',0),
(24623,'frFR','Pauvres petites choses.',0),
(24639,'frFR','La force, c''est pas tout pour vaincre ton ennemi, et c''est sûrement pas tout pour rester en vie. Se battre, c''est une question d''équilibre. Chaque chose a son temps et sa place.',0),
(24642,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(24759,'frFR','La puissance, c''est pas tout pour vaincre ton ennemi, et c''est sûrement pas tout pour rester en vie. Se battre, c''est une question d''équilibre. Chaque chose a son temps et sa place.',0),
(24762,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(24765,'frFR','La force, c''est pas tout pour vaincre ton ennemi, et c''est sûrement pas tout pour rester en vie. Se battre, c''est une question d''équilibre. Tu le verras mieux quand tu apprendras les formes animales, mais c''est déjà vrai maintenant. Chaque chose a son temps et sa place.',0),
(24768,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(24771,'frFR','La force, c''est pas tout pour vaincre ton ennemi, et c''est sûrement pas tout pour rester en vie. Se battre, c''est une question d''équilibre. Chaque chose a son temps et sa place.',0),
(24774,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(24777,'frFR','La visée, c''est pas tout pour vaincre ton ennemi, et c''est sûrement pas tout pour rester en vie. Se battre, c''est une question d''équilibre. Chaque chose a son temps et sa place.',0),
(24780,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(24783,'frFR','La puissance, c''est pas tout pour vaincre ton ennemi, et c''est sûrement pas tout pour rester en vie. Se battre, c''est une question d''équilibre. Chaque chose a son temps et sa place.',0),
(24786,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(25126,'frFR','J''espère que vous n''êtes pas $grevenu:revenue; me faire croire que vous avez accompli votre tâche, $n ? Non, bien sûr que non. J''ai meilleure opinion de vous.',0),
(25131,'frFR','Pour faire vos preuves face à la Lame ardente, vous devez d''abord vaincre ces vils familiers. Revenez me voir quand ce sera fait.',0),
(25172,'frFR','Vite, $n. Débarrassez notre vallée de ces humains.',0),
(26273,'frFR','La puissance vient de ce monde et de mondes que t''as pas encore vus. Maîtriser la puissance d''un seul suffira pas pour t''en sortir hors de ce terrain d''entraînement : faudra puiser ta puissance dans tous.',0),
(26276,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(26390,'frFR','Avez-vous trouvé Kurtok ?',0),
(27635,'frFR','Je parie que vous vous sentez déjà mieux.',0),
(29078,'frFR','Avez-vous repoussé les worgs de guerre de Rochenoire ?',0),
(29079,'frFR','Tuez les espions !',0),
(29081,'frFR','Tuez les assassins gobelins.',0),
(29406,'frFR','Les cibles d''entraînement sont juste en bas de la colline. Revenez me voir quand vous aurez terminé.',0),
(29408,'frFR','Viendra un moment où vous devrez vous fier à votre instinct et simplement agir.',0),
(29409,'frFR','Notre plus grande gloire n''est pas de ne jamais tomber, mais de nous relever à chaque chute. Jaomin Ro le sait. Il puise sa force dans chaque défaite.$B$BVous apprendrez peut-être cette leçon vous aussi.',0),
(29417,'frFR','Ne pas agir, c''est renoncer à la raison.',0),
(29419,'frFR','J''aurais dû être plus prudent.',0),
(29524,'frFR','Il y a un temps pour la méditation et la contemplation, et un temps pour l''action. Trouver l''équilibre entre les deux est l''une des plus grandes sagesses que nous recherchons.',0),
(29664,'frFR','Vous n''êtes pas encore $gprêt:prête; à m''affronter. Vous devez d''abord allumer les braseros.',0),
(29780,'frFR','Suivre la discipline des Huojin implique souvent de prendre des décisions difficiles. C''est l''un de ces moments.',0),
(30027,'frFR','Prendre sa première arme est aussi un geste symbolique. Chaque $c qui quitte ce terrain d''entraînement doit être prêt à prendre les armes pour défendre ses frères pandarens.',0),
(30033,'frFR','Prendre sa première arme est aussi un geste symbolique. Chaque $c qui quitte ce terrain d''entraînement doit être prêt à prendre les armes pour défendre ses frères pandarens.',0),
(31139,'frFR','Avez-vous repoussé les worgs de guerre de Rochenoire ?',0),
(31140,'frFR','Tuez les espions !',0),
(31144,'frFR','Tuez les assassins gobelins.',0),
(31158,'frFR','La force, c''est pas tout pour vaincre ton ennemi, et c''est sûrement pas tout pour rester en vie. Se battre, c''est une question d''équilibre. Chaque chose a son temps et sa place.',0),
(31161,'frFR','Tous les trolls doivent faire leurs preuves avant qu''on les laisse quitter le terrain d''entraînement.',0),
(37439,'frFR','Ce n''est ni une option ni un choix... vous devez étancher votre soif magique. Y échouer, c''est échouer en tant qu''elfe de sang. Ceux qui pensaient maîtriser leurs besoins sans enseignement font aujourd''hui partie des Misérables.$B$BVous ne voulez PAS finir en $gdrogué dément:droguée démente;. Croyez-moi.',0),
(37442,'frFR','Avez-vous lu la plaque du sanctuaire, alors, $c ?',0);
